#include<stdio.h>
typedef struct datastructure {
    int front;
    int rear;
    char q[101];
} DS;
int n;
char v;
DS d;

void f(char k) {
    d.front = d.rear = 50;
    d.q[50] = k;
}
void g(char k) {
    d.q[--(d.front)] = k;
}
void h(char k) {
    d.q[++(d.rear)] = k;
}
int main()
{
    scanf("%d", &n);
    scanf(" %c", &v);
    f(v);

    for(int i=0; i<n-1; i++) {
        scanf(" %c", &v);
        if(v <= d.q[d.front]) g(v);
        else                  h(v);
    }
    for(int i=d.front; i<=d.rear; i++) {
        printf("%c", d.q[i]);
    }
    return 0;
}

#include<stdio.h>
int n;
int *link[10];
int size[10], check[10], ans;

void search(int c, int p) {
    int count = 0;
    check[c] = 1;
    for(int i=0; i<size[c]; i++) {
        if(!check[ link[c][i] ]) {
            search(link[c][i], p+1);
            count++;
        }
    }
    if(count == 0) ans += p;
}

int main()
{
    scanf("%d", &n);

    for(int i=1; i<=n; i++) {
        link[i] = (int*)malloc(sizeof(int));
        link[i][0] = 0;
    }

    int p, q;
    for(int i=0; i<n-1; i++) {
        scanf("%d %d", &p, &q);

        link[p] = realloc(link[p], sizeof(int)*(size[p] + 1));
        link[p][size[p]] = q;
        size[p]++;

        link[q] = realloc(link[q], sizeof(int)*(size[q] + 1));
        link[q][size[q]] = p;
        size[q]++;
    }

    search(1, 0);
    printf("%d", ans);
    return 0;
}

